module curfew_enforcement(\n    input clk,\n    input rst_n,\n    input start,\n    input [4:0] n,\n    input [3:0] d,\n    input [7:0] b,\n    input [7:0] a [0:15],\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] COMPUTE_PREFIX = 4'd1;\n    localparam [3:0] COMPUTE_X      = 4'd2;\n    localparam [3:0] UPDATE_RESULT  = 4'd3;\n    localparam [3:0] FINISHED       = 4'd4;\n\n    reg [3:0] state;\n    reg [15:0] prefix [0:16];\n    reg [15:0] total_students;\n    reg [7:0] max_x;\n    reg [4:0] i;\n    reg [4:0] half_n;\n\n    integer j;\n    reg [7:0] left_index;\n    reg [7:0] right_index;\n    reg [15:0] available_left;\n    reg [15:0] available_right;\n    reg [15:0] available;\n    reg [7:0] rooms_filled;\n    reg [7:0] x_i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            max_x <= 8'd0;\n            total_students <= 16'd0;\n            i <= 5'd0;\n            for (j = 0; j <= 16; j = j + 1) begin\n                prefix[j] <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE_PREFIX;\n                        i <= 5'd0;\n                        total_students <= 16'd0;\n                        prefix[0] <= 16'd0;\n                    end\n                end\n\n                COMPUTE_PREFIX: begin\n                    if (i < n) begin\n                        total_students <= total_students + a[i];\n                        prefix[i+1] <= total_students + a[i];\n                        i <= i + 5'd1;\n                    end else begin\n                        i <= 5'd1;\n                        state <= COMPUTE_X;\n                        half_n <= (n + 5'd1) >> 1;\n                        max_x <= 8'd0;\n                    end\n                end\n\n                COMPUTE_X: begin\n                    if (i <= half_n) begin\n                        // Calculate left_index\n                        if (i * d < n) begin\n                            left_index <= i * d;\n                        end else begin\n                            left_index <= n;\n                        end\n\n                        // Calculate right_index\n                        if (n > i * d) begin\n                            right_index <= n - i * d;\n                        end else begin\n                            right_index <= 8'd0;\n                        end\n\n                        state <= UPDATE_RESULT;\n                    end else begin\n                        state <= FINISHED;\n                    end\n                end\n\n                UPDATE_RESULT: begin\n                    available_left = prefix[left_index];\n                    available_right = total_students - prefix[right_index];\n                    available = (available_left < available_right) ? available_left : available_right;\n                    rooms_filled = available / b;\n                    x_i = (i > rooms_filled) ? (i - rooms_filled) : 8'd0;\n\n                    if (x_i > max_x) begin\n                        max_x <= x_i;\n                    end\n\n                    i <= i + 5'd1;\n                    state <= COMPUTE_X;\n                end\n\n                FINISHED: begin\n                    result <= max_x;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule